package tv.casa.launcher;

import android.content.Context;
import android.net.*;
import android.media.MediaPlayer;
import android.os.*;
import android.view.Surface;

/** One decoder, muted from creation, released on every stop/error/network restriction. */
final class AmbientVideo {
    interface Events {void ready();void failed(String reason);void size(int width,int height);}
    private final Context context;private final Events events;private final Handler main=new Handler(Looper.getMainLooper());
    private HandlerThread thread;private Handler media;private MediaPlayer player;private volatile RangeMediaSource source;
    private volatile boolean stopped;private long started;private long progressAt;private int lastPosition;private boolean progressLogged;private final boolean wifiOnly;private final int maxWidth,minutes;
    AmbientVideo(Context c,Events e,boolean wifi,int width,int minutes){context=c.getApplicationContext();events=e;wifiOnly=wifi;maxWidth=width;this.minutes=minutes;}
    static boolean wifi(Context context){try{ConnectivityManager m=(ConnectivityManager)context.getSystemService(Context.CONNECTIVITY_SERVICE);Network n=m.getActiveNetwork();NetworkCapabilities cap=n==null?null:m.getNetworkCapabilities(n);return cap!=null&&cap.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)&&cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);}catch(Exception e){return false;}}
    void start(String url,Surface surface,long budget){if(thread!=null)return;if(wifiOnly&&!wifi(context)){fail("Vídeo omitido: Solo Wi-Fi está activo");return;}thread=new HandlerThread("AmbientVideo");thread.start();media=new Handler(thread.getLooper());media.post(()->{try{if(stopped)return;source=new RangeMediaSource(url,budget);if(stopped){source.close();return;}player=new MediaPlayer();player.setVolume(0f,0f);player.setSurface(surface);player.setLooping(true);player.setOnPreparedListener(p->{if(stopped)return;try{android.util.Log.i("CasaAmbient","MP4 prepared; bytes="+(source==null?0:source.bytes()));p.setVideoScalingMode(MediaPlayer.VIDEO_SCALING_MODE_SCALE_TO_FIT_WITH_CROPPING);p.setVolume(0f,0f);p.start();started=SystemClock.elapsedRealtime();progressAt=started;media.removeCallbacks(timeout);media.postDelayed(timeout,10000);media.postDelayed(monitor,1000);}catch(Exception e){fail("No se pudo iniciar el vídeo");}});player.setOnInfoListener((p,what,extra)->{if(what==MediaPlayer.MEDIA_INFO_VIDEO_RENDERING_START){android.util.Log.i("CasaAmbient","MP4 first frame");media.removeCallbacks(timeout);main.post(()->{if(!stopped)events.ready();});}return false;});player.setOnVideoSizeChangedListener((p,w,h)->{if(w>maxWidth||h>maxWidth*9/16+8){fail("El vídeo supera la calidad elegida");return;}main.post(()->{if(!stopped)events.size(w,h);});});player.setOnErrorListener((p,what,extra)->{android.util.Log.w("CasaAmbient","MP4 error "+what+"/"+extra+"; bytes="+(source==null?0:source.bytes()));fail("Vídeo no disponible o límite de datos alcanzado");return true;});player.setDataSource(source);player.prepareAsync();media.postDelayed(timeout,15000);}catch(Exception e){fail("No se pudo preparar el vídeo; se muestran imágenes");}});}
    private final Runnable timeout=()->{android.util.Log.w("CasaAmbient","MP4 timeout; bytes="+(source==null?0:source.bytes()));fail("La carga de vídeo tardó demasiado");};
    private final Runnable monitor=new Runnable(){public void run(){if(stopped)return;try{if(wifiOnly&&!wifi(context)){fail("Vídeo detenido al salir de Wi-Fi");return;}long now=SystemClock.elapsedRealtime();int position=player==null?0:player.getCurrentPosition();if(position!=lastPosition){lastPosition=position;progressAt=now;}if(now-progressAt>15000){fail("El vídeo dejó de avanzar; se muestran imágenes");return;}if(!progressLogged&&now-started>10000){progressLogged=true;android.util.Log.i("CasaAmbient","MP4 progress; position="+position+"; bytes="+(source==null?0:source.bytes()));}if(SystemClock.elapsedRealtime()-started>=minutes*60000L){fail("Se alcanzó el tiempo de vídeo elegido");return;}media.postDelayed(this,1000);}catch(Exception e){fail("El reproductor no pudo continuar");}}};
    private void fail(String message){main.post(()->{if(!stopped){events.failed(message);stop();}});}
    void stop(){if(stopped)return;stopped=true;RangeMediaSource active=source;if(active!=null)active.close();main.removeCallbacksAndMessages(null);Handler h=media;HandlerThread t=thread;if(h!=null){h.removeCallbacksAndMessages(null);h.post(()->{try{if(player!=null){player.setOnErrorListener(null);player.setOnPreparedListener(null);player.release();player=null;}}finally{if(source!=null){source.close();source.clearCache();}if(t!=null)t.quitSafely();}});}else if(t!=null)t.quitSafely();}
}
